import { ObjectSchema } from "./utils/plugin-options-schema-joi-type"

interface ITestPluginOptionsSchemaResult {
  isValid: boolean
  errors: Array<string>
}

// Utility to test that a plugin's options schema validates a given set of
// options the way the plugin author expects, without having to run a full
// Gatsby build. Only the fields present in `pluginOptions` are validated, so
// authors can assert the behaviour of individual options in isolation - even
// when other fields are required by the schema.
export function testPluginOptionsSchema(
  pluginSchemaFunction: ({ Joi }: { Joi: any }) => ObjectSchema,
  pluginOptions: object
): ITestPluginOptionsSchemaResult {
  const pluginSchema = pluginSchemaFunction({ Joi })

  const errors: Array<string> = []

  Object.keys(pluginOptions).forEach(key => {
    let fieldSchema
    try {
      fieldSchema = pluginSchema.extract(key)
    } catch (e) {
      // The field isn't part of the schema, so there's nothing to validate.
      return
    }

    const { error } = Joi.object({ [key]: fieldSchema }).validate(
      { [key]: pluginOptions[key] },
      { abortEarly: false }
    )

    if (!error) {
      return
    }

    // Array item errors carry a path deeper than the field itself (e.g.
    // `["arr", 0]`). Collapse them into a single entry so the message reads
    // `"arr" "[0]" must be a string. "[1]" must be a string`.
    const isArrayField = error.details.some(detail => detail.path.length > 1)

    if (isArrayField) {
      const itemErrors = error.details.map(detail =>
        detail.message.replace(`"${key}[`, `"[`)
      )

      errors.push(`"${key}" ${itemErrors.join(`. `)}`)
    } else {
      error.details.forEach(detail => {
        errors.push(detail.message)
      })
    }
  })

  return {
    isValid: errors.length === 0,
    errors,
  }
}
